'use strict';
(async function(){
const {parts,joints,assembly,counts,item,pin}=OBTPCatalogue,$=id=>document.getElementById(id);let selected='W-S',view='object',joint='wall-wall',explode=0,layer='all',isolate='',token=0;const cache=new Map();let renderer;
try{renderer=new SourceMeshView($('diagram'));}catch(e){$('status').textContent=e.message;return;}
async function load(id){if(!cache.has(id))cache.set(id,fetch(`catalogue/${id}.json`).then(r=>{if(!r.ok)throw Error('Could not load '+id);return r.json();}).then(m=>{if(m.schema!=='obtp-source-mesh/1'||m.units!=='mm'||!m.assets?.length)throw Error('Unexpected geometry '+id);renderer.register(m);return m;}).catch(e=>{cache.delete(id);throw e;}));return cache.get(id);}
async function render(){const stamp=++token,p=parts.find(p=>p.id===selected),j=joints.find(j=>j.id===joint);$('types').innerHTML=[...new Set(parts.map(p=>p.type))].map(t=>`<button data-type="${t}" aria-pressed="${p.type===t}">${t}<span>${parts.filter(p=>p.type===t).length}</span></button>`).join('');$('objects').innerHTML=parts.filter(a=>a.type===p.type).map(a=>`<button data-part="${a.id}" aria-pressed="${selected===a.id}">${a.id}</button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));$('family').textContent=view==='assembly'?'Skylark 150 / source geometry fit study':p.type+' / official source';$('title').textContent=view==='object'?p.id:view==='connection'?j.name:'One chassis slice';$('connections').hidden=view!=='connection';$('connections').innerHTML=joints.map(a=>`<button data-joint="${a.id}" aria-pressed="${joint===a.id}">${a.name}</button>`).join('');$('connection-note').hidden=view!=='connection';$('connection-note').textContent=j.rule+' '+j.evidence;$('assembly-controls').hidden=view!=='assembly';$('schedule').hidden=view!=='assembly';$('part').disabled=view!=='object';$('explode-value').textContent=explode+'%';$('status').textContent='Loading source geometry…';$('drawing-label').textContent=view==='object'?'SOURCE PARTS / '+selected:view==='connection'?'DOCUMENTED INTERFACE / GEOMETRIC FIT':'OPEN CHASSIS SLICE / '+layer.toUpperCase();
 const items=view==='object'?[item(selected)]:view==='connection'?j.scene():assembly(layer);try{const ids=[...new Set(items.map(i=>i.block))];const models=await Promise.all(ids.map(load));if(stamp!==token)return;
 if(view==='object'){const m=models[0];$('part').innerHTML='<option value="">All source parts</option>'+m.assets.map((a,i)=>`<option value="${i}">${a.label} · ${a.id.slice(0,8)}</option>`).join('');$('part').value=isolate;const dims=m.bounds[1].map((v,i)=>v-m.bounds[0][i]);$('details').innerHTML=`<div><span class="eyebrow">Role</span><p>${p.role}</p><p>${p.note}</p></div><div><span class="eyebrow">Source envelope</span><p><strong>${dims.map(v=>v.toFixed(1)).join(' × ')} mm</strong></p><p>${m.assets.length} source part instances</p></div><div><span class="eyebrow">Provenance</span><p><a href="https://github.com/wikihouseproject/Skylark/blob/${pin}/SKYLARK150/${p.source}">Official source file ↗</a></p><p><a href="catalogue/${p.id}.json" download>Download display mesh</a></p><p>${isolate!==''?'Source ID: '+m.assets[Number(isolate)].id:'Original source IDs retained.'}</p></div>`;}
 else if(view==='connection'){$('details').innerHTML=`<div><span class="eyebrow">Components</span><p>${j.ids.join(' + ')}</p></div><div><span class="eyebrow">Connection</span><p>Official full tie and matching source sockets. No new joint shape.</p></div><div><span class="eyebrow">Validation</span><p>Sampled profile fit; not full collision, assembly-access or strength verification.</p></div>`;}
 else{$('details').innerHTML='<div><span class="eyebrow">Setting-out</span><p><strong>600 × 4,572 mm</strong> floor module</p><p>2,100 mm wall block; source roof fall retained.</p></div><div><span class="eyebrow">Assembly</span><p>One floor + two walls + one roof</p><p>24 ties at floor/wall and wall/roof interfaces.</p></div><div><span class="eyebrow">Scope</span><p>Open slice, not a complete building. End walls, foundations and bracing are absent.</p></div>';$('schedule').innerHTML='<h3>Shown component quantities</h3><table><thead><tr><th>Object</th><th>Count</th><th>Role</th></tr></thead><tbody>'+counts(items).map(r=>`<tr><td>${r.id}</td><td>${r.count}</td><td>${parts.find(p=>p.id===r.id).role}</td></tr>`).join('')+'</tbody></table>';}
 renderer.setScene(items,{explode:explode/100,isolate,object:view==='object'});$('status').textContent=`${items.length} component instances · ${models.reduce((n,m)=>n+m.assets.length,0)} source part instances in loaded definitions · ready`;window.OBTPSystem={selected,view,joint,layer,items,models,renderer};
 }catch(e){if(stamp!==token)return;renderer.setScene([]);$('status').textContent=e.message;console.error(e);}}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let changed=false;if(b.dataset.type){selected=parts.find(p=>p.type===b.dataset.type).id;view='object';changed=true;}if(b.dataset.part){selected=b.dataset.part;view='object';changed=true;}if(b.dataset.view){view=b.dataset.view;if(view==='connection')joint=joints.find(j=>j.ids.includes(selected))?.id||joint;changed=true;}if(b.dataset.joint){joint=b.dataset.joint;changed=true;}if(changed){isolate='';explode=0;$('explode').value=0;renderer.reset();render();}});$('explode').oninput=e=>{explode=Number(e.target.value);$('explode-value').textContent=explode+'%';renderer.explode=explode/100;renderer.draw();};$('part').onchange=e=>{isolate=e.target.value;render();};$('layer').onchange=e=>{layer=e.target.value;render();};$('reset').onclick=()=>renderer.reset();await render();
})();
